<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; admin_requerido(); $error=''; $editar=null;
if($_SERVER['REQUEST_METHOD']==='POST'){ validar_csrf(); $accion=$_POST['accion']??''; try { if($accion==='guardar'){ $id=(int)($_POST['id']??0); $nombre=trim($_POST['nombre']??''); $ciudad=trim($_POST['ciudad']??''); $entrenador=trim($_POST['entrenador']??''); if($nombre==='') throw new RuntimeException('El nombre del equipo es obligatorio.'); if($id){$s=$pdo->prepare('UPDATE equipos SET nombre=?,ciudad=?,entrenador=? WHERE id=?');$s->execute([$nombre,$ciudad?:null,$entrenador?:null,$id]);}else{$s=$pdo->prepare('INSERT INTO equipos(nombre,ciudad,entrenador) VALUES(?,?,?)');$s->execute([$nombre,$ciudad?:null,$entrenador?:null]);} header('Location: equipos.php?ok=1');exit; } elseif($accion==='eliminar'){ $id=(int)($_POST['id']??0); $s=$pdo->prepare('DELETE FROM equipos WHERE id=?');$s->execute([$id]);header('Location: equipos.php?eliminado=1');exit; } }catch(Throwable $ex){$error=$ex instanceof PDOException?'No se pudo guardar/eliminar. Verifica que el nombre no esté repetido y que el equipo no tenga jugadores o partidos asociados.':$ex->getMessage();} }
if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM equipos WHERE id=?');$s->execute([(int)$_GET['editar']]);$editar=$s->fetch();}
$equipos=$pdo->query('SELECT e.*,COUNT(j.id) AS total_jugadores FROM equipos e LEFT JOIN jugadores j ON j.equipo_id=e.id GROUP BY e.id ORDER BY e.nombre')->fetchAll(); $pageTitle='Gestionar equipos'; require __DIR__.'/../src/header.php'; ?>
<section class="page-intro"><span class="eyebrow">ADMINISTRACIÓN</span><h1>Equipos</h1><p>Registra los equipos y actualiza sus datos.</p></section>
<?php if($error): ?><div class="alert alert-error"><?= e($error) ?></div><?php endif; ?><?php if(isset($_GET['ok'])): ?><div class="alert alert-success">Equipo guardado correctamente.</div><?php endif; ?><?php if(isset($_GET['eliminado'])): ?><div class="alert alert-success">Equipo eliminado.</div><?php endif; ?>
<div class="admin-two-col"><form class="form-card" method="post"><h2><?= $editar?'Editar equipo':'Registrar equipo' ?></h2><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id" value="<?= (int)($editar['id']??0) ?>"><label>Nombre del equipo *<input name="nombre" required maxlength="100" value="<?= e($editar['nombre']??'') ?>"></label><label>Ciudad<input name="ciudad" maxlength="100" value="<?= e($editar['ciudad']??'') ?>"></label><label>Entrenador<input name="entrenador" maxlength="100" value="<?= e($editar['entrenador']??'') ?>"></label><button class="btn" type="submit">Guardar equipo</button><?php if($editar): ?><a class="back-link" href="equipos.php">Cancelar edición</a><?php endif; ?></form><section><h2 class="list-title">Equipos registrados (<?= count($equipos) ?>)</h2><?php if(!$equipos): ?><div class="empty-state">No hay equipos registrados.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Equipo</th><th>Ciudad</th><th>Jug.</th><th>Acciones</th></tr></thead><tbody><?php foreach($equipos as $t): ?><tr><td><strong><?= e($t['nombre']) ?></strong><small class="table-sub"><?= e($t['entrenador']?:'Sin entrenador') ?></small></td><td><?= e($t['ciudad']?:'—') ?></td><td><?= (int)$t['total_jugadores'] ?></td><td class="actions-cell"><a href="?editar=<?= (int)$t['id'] ?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este equipo? Solo se podrá si no tiene jugadores ni partidos asociados.');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><button class="link-danger" type="submit">Eliminar</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php require __DIR__.'/../src/footer.php'; ?>